arguments.command:
OPENBLAS_NUM_THREADS=1 python - <<'PY'
import pickle,numpy as np
tr,po,ss,X,info=pickle.load(open('features.pkl','rb'))
for ii in [50,59,91,65,66,67,47,48]:
 s=ss[200+ii];print('\n',po.candidate_id.iloc[ii],po.formula.iloc[ii])
 for i in range(len(s)):
  if s[i].specie.symbol in ['C','S','Te','Zn','F']:
   near=sorted(s.get_neighbors(s[i],3.5),key=lambda x:x.nn_distance)
   print(i, s[i].specie, [(a.specie.symbol,round(a.nn_distance,3)) for a in near[:12]])
   if s[i].specie.symbol in ['S','Zn','C']:
    u=np.array([a.coords-s[i].coords for a in near[:4]]);u=u/np.linalg.norm(u,axis=1)[:,None];print('angles',np.arccos(np.clip(u@u.T,-1,1))*180/np.pi)
